import sys, json, random, subprocess, copy
sys.path.insert(0, "/workspace/tests")
from run_sub import run

random.seed(4242)
NAMES = ["a.t.","b.t.","c.t.","x.y.t.","t.","*.t.","d.e.t.","q.*.t.","z.t.","sub.t.","w.sub.t.",".","other.","deep.a.b.t."]
TYPES = ["A","AAAA","TXT","CNAME"]

def rand_doc(rng):
    nzones = rng.randint(0,3)
    origins = ["t.","sub.t.","." ,"other."]
    rng.shuffle(origins)
    zones=[]
    for i in range(nzones):
        recs=[]
        for _ in range(rng.randint(0,6)):
            o=rng.choice(NAMES); ty=rng.choice(TYPES)
            if ty=="A": d="%d.%d.%d.%d"%tuple(rng.randint(0,255) for _ in range(4))
            elif ty=="AAAA": d="2001:db8::%d"%rng.randint(0,99)
            elif ty=="TXT": d="t%d"%rng.randint(0,99)
            else: d=rng.choice(NAMES)
            recs.append({"owner":o,"type":ty,"data":d})
        zones.append({"origin":origins[i],"records":recs})
    profiles=[{"id":"p%d"%i,"max_aliases":rng.randint(0,4),"cname":rng.choice(["follow","stop"]),
               "wildcard":rng.choice(["rfc","off","one-label"])} for i in range(rng.randint(1,5))]
    queries=[{"id":"q%d"%i,"name":rng.choice(NAMES),"type":rng.choice(TYPES),"cost":rng.randint(1,9)} for i in range(rng.randint(0,6))]
    obs=[]
    for i in range(rng.randint(0,5)):
        if not queries or not profiles: break
        if rng.random()<0.3:
            res={"status":"timeout"}
        else:
            res={"status":"response","rcode":rng.choice(["NOERROR","NXDOMAIN","SERVFAIL","REFUSED"]),
                 "answer":[{"owner":rng.choice(NAMES),"type":rng.choice(TYPES),
                            "data":(rng.choice(["1.2.3.4","2001:db8::1","txt","a.t."]) if rng.random()<0.8 else "bad")}
                           for _ in range(rng.randint(0,3))]}
        obs.append({"id":"o%d"%i,"query":rng.choice(queries)["id"],"profile":rng.choice(profiles)["id"],"result":res})
    return {"zones":zones,"profiles":profiles,"queries":queries,"observations":obs}

MUT = ["deletekey","addkey","wrongtype","null","dupkey","badname","baddata","negative","huge","truncate"]

def mutate(doc, rng):
    d = copy.deepcopy(doc)
    op = rng.choice(MUT)
    if op=="deletekey" and d["zones"]:
        z = rng.choice(d["zones"])
        if z["records"]: z["records"].pop(rng.randrange(len(z["records"])))
    elif op=="addkey":
        d["extra_key"] = 1
    elif op=="wrongtype":
        d["queries"] = {"not":"a list"}
    elif op=="null":
        d["observations"] = None
    elif op=="dupkey":
        return json.dumps(d).replace('"queries"', '"queries"', 1)  # placeholder
    elif op=="badname" and d["queries"]:
        q = rng.choice(d["queries"]); q["name"] = rng.choice(["rel","a..b.","x y.","",".x.","*"])
    elif op=="baddata" and d["zones"] and d["zones"][0]["records"]:
        r = rng.choice(d["zones"][0]["records"]); r["data"] = rng.choice(["1.2.3","1.2.3.4.5","01.2.3.4","256.1.1.1","", "x"*300])
    elif op=="negative" and d["queries"]:
        rng.choice(d["queries"])["cost"] = -1
    elif op=="huge":
        d["profiles"] = d["profiles"] * 12
    elif op=="truncate":
        return json.dumps(d)[:rng.randint(1,50)]
    return json.dumps(d)

nvalid=0; ninvalid=0
for trial in range(600):
    rng = random.Random(trial)
    doc = rand_doc(rng)
    raw = json.dumps(doc).encode()
    out = run(doc, raw)
    assert isinstance(out, dict)
    if "error" in out:
        assert out == {"error":"invalid-input"}, out
        ninvalid += 1
    else:
        assert set(out) == {"runs","audits","diagnostic"}, out
        nvalid += 1
    mraw = mutate(doc, rng).encode()
    out2 = run(None, mraw) if False else None
    p = subprocess.run([sys.executable,"-I","/workspace/submission/main.py"], input=mraw, capture_output=True)
    assert p.returncode == 0, (p.returncode, p.stderr[:300])
    assert p.stderr == b"", p.stderr[:300]
    try:
        o2 = json.loads(p.stdout)
    except Exception:
        raise AssertionError("bad json %r" % p.stdout[:300])
    assert isinstance(o2, dict)
    if "error" in o2: assert o2 == {"error":"invalid-input"}
print("fuzz subprocess OK: valid=%d invalid=%d" % (nvalid, ninvalid))
PYEOF
cd /workspace/tests && python3 test_fuzz_subprocess.py
